import React, { useEffect, useMemo, useState } from 'react';
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  Grid,
  TextField,
  DialogTitle,
  Typography,
  Box,
  Divider,
} from '@mui/material';
import { useTranslation } from 'react-i18next';
import FieldHeader from '../../../components/FieldHeader';
import { selectBasketItems } from '../store/BasketSelector';
import { useSelector } from 'react-redux';
import { IProductData } from '../../../core/Interface/product.interface';

interface IAlertPopup {
  open: boolean;
  handleCloseAlert: () => void;
  handleAdd: (
    calculatedValue: number | null,
    inputCount: number,
    goldData?: {
      goldPrice8g: number;
      goldWeightQty: number;
      goldWasteQty: number;
      goldCarrot: string;
      makingCharge: number;
    }
  ) => void;
  product: IProductData;
  editGoldData?: {
    goldWeightQty: number;
    goldWasteQty: number;
    goldCarrot: string;
    makingCharge: number;
    goldPrice8g: number;
  };
}

const toNum = (v: string) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : 0;
};

const AlertPopup: React.FC<IAlertPopup> = ({
  open,
  handleCloseAlert,
  product,
  handleAdd,
  editGoldData,
}) => {
  const { t } = useTranslation(['common']);
  const selectItem = useSelector(selectBasketItems);
  const selectedItem = selectItem.find((item) => item.id === product.id);

  const [goldPrice8g, setGoldPrice8g] = useState<number>(0);
  const [karatText, setKaratText] = useState<string>('22K');
  const [weightG, setWeightG] = useState<string>('');
  const [making, setMaking] = useState<string>('');
  const [wastage, setWastage] = useState<string>('');

  useEffect(() => {
    if (selectedItem) {
    }
    setGoldPrice8g(product.unitPrice);
    if (editGoldData) {
      setGoldPrice8g(editGoldData.goldPrice8g);
      setWeightG(editGoldData.goldWeightQty.toString());
      setMaking(editGoldData.makingCharge.toString());
      setWastage(editGoldData.goldWasteQty.toString());
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editGoldData, selectedItem]);

  const handleClose = () => handleCloseAlert();

  const perGram24 = useMemo(
    () => (goldPrice8g > 0 ? goldPrice8g / 8 : 0),
    [goldPrice8g]
  );

  const weightValue = useMemo(() => toNum(weightG), [weightG]);
  const goldPriceForWeight = useMemo(
    () => perGram24 * weightValue,
    [perGram24, weightValue]
  );

  const wastageGrams = useMemo(() => toNum(wastage), [wastage]);
  const wastageAmount = useMemo(
    () => perGram24 * wastageGrams,
    [perGram24, wastageGrams]
  );

  const finalUnitPrice = useMemo(() => {
    const mk = toNum(making);
    if (perGram24 <= 0 || weightValue <= 0) return null;
    const total = goldPriceForWeight + mk + wastageAmount;
    return total >= 0 ? total : 0;
  }, [perGram24, weightValue, making, goldPriceForWeight, wastageAmount]);

  const handleAddClick = () => {
    if (finalUnitPrice !== null) {
      const goldData = {
        goldWeightQty: weightValue,
        goldWasteQty: wastageGrams,
        goldCarrot: karatText,
        makingCharge: toNum(making),
        goldPrice8g: goldPrice8g,
      };
      handleAdd(finalUnitPrice, 1, goldData);
      handleClose();
    }
  };

  const fmt = (n: number | null | undefined) =>
    n === null || n === undefined ? '--' : n.toFixed(2);

  // eslint-disable-next-line react/no-multi-comp
  const Row = ({
    label,
    value,
    hint,
    strong = false,
  }: {
    label: string;
    value: number | null | undefined;
    hint?: React.ReactNode;
    strong?: boolean;
  }) => (
    <Box
      sx={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'baseline',
        py: 0.75,
      }}
    >
      <Typography
        sx={{ fontWeight: strong ? 700 : 500 }}
        variant="body1"
      >
        {label} {hint ? <em style={{ opacity: 0.7 }}>{hint}</em> : null}
      </Typography>
      <Typography
        sx={{ fontWeight: strong ? 700 : 600 }}
        variant={strong ? 'h6' : 'body1'}
      >
        {fmt(value as number)}
      </Typography>
    </Box>
  );

  return (
    <Dialog
      fullWidth
      maxWidth="sm"
      onClose={handleClose}
      open={open}
    >
      <DialogTitle sx={{ background: '#CFD8DC', borderRadius: 1, p: 4, py: 2 }}>
        <strong>Details of {product.name}</strong>
      </DialogTitle>
      <DialogContent sx={{ p: 4, pt: 3 }}>
        <Grid
          container
          spacing={2}
        >
          <Grid
            item
            xs={12}
          >
            <FieldHeader title="Gold Price (8g)" />
            <TextField
              autoComplete="off"
              fullWidth
              onChange={(e) => setGoldPrice8g(parseInt(e.target.value))}
              placeholder="Enter 8g gold price"
              size="small"
              type="number"
              inputProps={{ step: 'any' }}
              value={goldPrice8g}
            />
          </Grid>

          <Grid
            item
            xs={12}
          >
            <FieldHeader title="Karat (purity)" />
            <TextField
              autoComplete="off"
              fullWidth
              onChange={(e) => setKaratText(e.target.value)}
              placeholder="e.g., 22K, 18K"
              size="small"
              value={karatText}
            />
          </Grid>

          <Grid
            item
            xs={12}
          >
            <FieldHeader title="Gold weight (g)" />
            <TextField
              autoComplete="off"
              fullWidth
              onChange={(e) => setWeightG(e.target.value)}
              placeholder="Enter gold weight (g)"
              size="small"
              type="number"
              inputProps={{ step: 'any' }}
              value={weightG}
            />
          </Grid>

          <Grid
            item
            xs={12}
          >
            <FieldHeader title="Making Charges" />
            <TextField
              autoComplete="off"
              fullWidth
              onChange={(e) => setMaking(e.target.value)}
              placeholder="Enter making charges (amount)"
              size="small"
              type="number"
              inputProps={{ step: 'any' }}
              value={making}
            />
          </Grid>

          <Grid
            item
            xs={12}
          >
            <FieldHeader title="Wastage (g)" />
            <TextField
              autoComplete="off"
              fullWidth
              onChange={(e) => setWastage(e.target.value)}
              placeholder="Enter wastage in grams"
              size="small"
              type="number"
              inputProps={{ step: 'any' }}
              value={wastage}
            />
          </Grid>

          <Grid
            item
            xs={12}
          >
            <Box
              sx={{
                border: '1px dashed #B0BEC5',
                borderRadius: 2,
                p: 2,
                background: '#F7FAFC',
              }}
            >
              <Row
                label="8g gold price"
                value={goldPrice8g}
              />
              <Row
                hint={
                  perGram24 > 0 && weightValue > 0 ? (
                    <>
                      {' '}
                      ( {fmt(perGram24)} × {weightG || '0'} )
                    </>
                  ) : undefined
                }
                label={`${weightG || '0'}g gold price`}
                value={goldPriceForWeight}
              />
              <Row
                label="Making charges"
                value={toNum(making)}
              />
              <Row
                hint={
                  wastageGrams > 0 && perGram24 > 0 ? (
                    <>
                      {' '}
                      ( {fmt(perGram24)} × {wastage || '0'}g )
                    </>
                  ) : undefined
                }
                label={`Wastage price (${wastage || '0'}g)`}
                value={wastageAmount}
              />
              <Divider sx={{ my: 1 }} />
              <Row
                label="Final amount (per item)"
                strong
                value={finalUnitPrice ?? null}
              />
            </Box>
          </Grid>
        </Grid>
      </DialogContent>

      <DialogActions sx={{ px: 4, py: 2, gap: 2 }}>
        <Button
          color="primary"
          onClick={handleClose}
          sx={{
            width: 150,
            height: 42,
            borderRadius: '5px',
            fontWeight: 'bold',
          }}
          variant="outlined"
        >
          {t('common:cancel')}
        </Button>
        <Button
          autoFocus
          color="primary"
          disabled={finalUnitPrice === null}
          onClick={handleAddClick}
          sx={{
            width: 150,
            height: 42,
            borderRadius: '5px',
            fontWeight: 'bold',
          }}
          type="button"
          variant="contained"
        >
          Add
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default AlertPopup;
