import { useSelector } from 'react-redux';
import {
  finalSummaryStare,
  selectBasket,
  selectBasketItems,
  selectDiscount,
  selectReceivedAmount,
} from './store/BasketSelector';
import { useMemo } from 'react';
import {
  IPreOrderJewelleryBasketItem,
  IPreOrderJewellerySalesItem,
  IPreOrderJewellerySalesReqPayload,
} from '../../core/Interface/preOrderJewellery.interface';

const toFixedDown = (num: number): number => Math.round(num * 100) / 100;

const useSales = () => {
  const items = useSelector(selectBasketItems);
  const discountData = useSelector(selectDiscount);
  const paymentStatus = useSelector(finalSummaryStare);
  const receivedAmount = useSelector(selectReceivedAmount);
  const basketStore = useSelector(selectBasket);

  const calculateSummary = useMemo(() => {
    const subTotal = items.reduce(getSum, 0);
    const discount = discountData.discountAsPercentage
      ? (subTotal * (discountData.discount ?? 0)) / 100
      : discountData.discount ?? 0;
    const total = subTotal === 0 ? 0 : subTotal - discount;

    return {
      subTotal: toFixedDown(subTotal),
      discount: toFixedDown(discount),
      total: toFixedDown(total),
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    items,
    discountData.discount,
    discountData.discountAsPercentage,
    receivedAmount,
  ]);

  const salesDetails: IPreOrderJewellerySalesReqPayload = {
    mobile: basketStore.mobile ?? '',
    customerName: basketStore.customerName ?? '',
    deliveryDateTime: basketStore.deliveryDateTime || new Date().toISOString(),
    subTotal: calculateSummary.subTotal,
    discount: calculateSummary.discount,
    total: calculateSummary.total,
    netTotal: calculateSummary.total,
    isDiscountPercentage: !!discountData.discountAsPercentage,
    discountValue: toFixedDown(discountData.discount ?? 0),
    totalDiscount: calculateSummary.discount,
    received: basketStore.received ?? 0,
    balance: toFixedDown(
      (basketStore.received ?? 0) +
        (basketStore.returnAmount ?? 0) -
        calculateSummary.total
    ),
    items: items.map((item) => {
      const itemUnitPrice = item.calculatedUnitPrice ?? item.unitPrice;

      const lineDiscount = item.defaultDiscountAmount
        ? item.isDiscountPercentage
          ? ((itemUnitPrice * (item.defaultDiscountAmount ?? 0)) / 100) *
            item.count
          : (item.defaultDiscountAmount ?? 0) * item.count
        : 0;

      const guidProductId = String(item.id).split('__v')[0];

      return {
        productId: guidProductId,
        qty: item.count,
        goldWeightQty: item.goldWeightQty ?? 0,
        goldWasteQty: item.goldWasteQty ?? 0,
        goldCarrot: item.goldCarrot ?? '22K',
        makingCharge: item.makingCharge ?? 0,
        unitPrice: toFixedDown(item.goldPrice8g ?? 0),
        amount: toFixedDown(itemUnitPrice * item.count - lineDiscount),
      } as IPreOrderJewellerySalesItem;
    }),
    whatsAppShareLink: '',
    paymentMethod: basketStore.paymentMethod ?? '',
    isPaid: true,
    dateTime: new Date().toISOString(),
  };

  return { calculateSummary, items, salesDetails, paymentStatus };
};

function getSum(total: number, item: IPreOrderJewelleryBasketItem) {
  return (
    total +
    (item.goldWeightQty ?? 0) * ((item.goldPrice8g ?? 0) / 8) +
    (item.makingCharge ?? 0) +
    (item.goldWasteQty ?? 0) * ((item.goldPrice8g ?? 0) / 8)
  );
}

export default useSales;
